"""results.json -> REPORT.md (gates per tier, repeatability, head-to-head, timing)."""
from __future__ import annotations


def _num(x, nd=3, unit=""):
    return "–" if x is None else f"{x:.{nd}f}{unit}"


def _cm(x):
    return "–" if x is None else f"{100 * x:+.1f}"


def _pct(x):
    return "–" if x is None else f"{100 * x:+.1f}%"


def _pf(b):
    return "PASS" if b else "FAIL"


def write_report(results: dict, caps: list[dict], path) -> None:
    C = results["captures"]
    L = ["# Benchmark report", "",
         "Generated by `python -m benchmark.evaluate`. Every number regenerates from "
         "`benchmark/captures.json`, `benchmark/gt/` and the raw captures.", ""]

    L += ["## Gates", "", "| capture | tier | gate | value | result | detail |",
          "|---|---|---|---|---|---|"]
    for cid, s in C.items():
        for g, v in s["gates"].items():
            L.append(f"| {cid} | {s['tier']} | {g} | {_num(v['value'])} | {_pf(v['pass'])} | {v['detail']} |")

    L += ["", "## Wall lengths", "",
          "| capture | room | wall | GT (m) | ours (m) | error (cm) | in 90% CI |",
          "|---|---|---|---|---|---|---|"]
    for cid, s in C.items():
        for w in s["walls"]:
            L.append(f"| {cid} | {w['room']} | {w['wall']} | {w['gt']:.3f} | {w['pred']:.3f} | "
                     f"{_cm(w['err'])} | {'yes' if w['covered'] else 'no'} |")

    L += ["", "## Openings", "", "| capture | room | kind | GT (m) | ours (m) | error (cm) | status |",
          "|---|---|---|---|---|---|---|"]
    for cid, s in C.items():
        for o in s["openings"]:
            L.append(f"| {cid} | {o['room']} | {o['kind']} | {_num(o['gt'])} | {_num(o['pred'])} | "
                     f"{_cm(o['err'])} | {o['status']} |")

    L += ["", "## Ceiling height", "", "| capture | room | GT (m) | ours (m) | error (cm) |",
          "|---|---|---|---|---|"]
    for cid, s in C.items():
        for c in s["ceiling"]:
            err = "not observed" if c["err"] is None else _cm(c["err"])
            L.append(f"| {cid} | {c['room']} | {c['gt']:.3f} | {_num(c['pred'])} | {err} |")

    L += ["", "## Stitched plan", "",
          "| capture | adjacency correct | missing | extra | overlap (m²) | footprint GT | ours | error |",
          "|---|---|---|---|---|---|---|---|"]
    for cid, s in C.items():
        a, fp = s["adjacency"], s["footprint"]
        L.append(f"| {cid} | {a['correct']} | {a['missing']} | {a['extra']} | {s['overlap_m2']:.3f} | "
                 f"{_num(fp['gt'], 2)} | {fp['pred']:.2f} | {_pct(fp['rel'])} |")

    L += ["", "## Drift ablation", "",
          "| capture | drift method | max correction (m) | loop closures | footprint error |",
          "|---|---|---|---|---|"]
    for cid, s in C.items():
        d = s["drift"]
        L.append(f"| {cid} | {d['method']} | {_num(d.get('correction_m'))} | "
                 f"{d.get('loop_closures')} | {_pct(s['footprint']['rel'])} |")

    L += ["", "## Repeatability", ""]
    for cid, r in results["repeatability"].items():
        L += [f"**{cid}**: {_pf(r['pass'])}", "",
              "| room | wall | run A (m) | run B (m) | diff (cm) | ≤1 cm or 0.5% |",
              "|---|---|---|---|---|---|"]
        L += [f"| {w['room']} | {w['wall']} | {w['a']:.3f} | {w['b']:.3f} | {100 * w['diff']:.1f} | "
              f"{_pf(w['pass'])} |" for w in r["walls"]]
        for c in r["ceiling"]:
            L.append(f"\nCeiling {c['room']}: spread {100 * c['spread']:.1f} cm, bias "
                     f"{100 * c['bias']:+.1f} cm → **{c['verdict']}**")
        L.append("")

    L += ["## Head-to-head", "",
          "Tie = our absolute error within 0.5 cm of theirs.", ""]
    for cid, s in C.items():
        h = s.get("head_to_head")
        if not h:
            continue
        frac = h["beat_or_tie_frac"] or 0
        L += [f"**{cid}** vs {h['app']} {h['version']}: beat or tie on {100 * frac:.0f}% "
              f"(gate ≥ 70%: {_pf(h['pass'])})", "",
              "| dimension | GT (m) | our error (cm) | their error (cm) | beat/tie |",
              "|---|---|---|---|---|"]
        L += [f"| {r['dim']} | {r['gt']:.3f} | {_cm(r['ours_err'])} | {_cm(r['theirs_err'])} | "
              f"{'yes' if r['beat_or_tie'] else 'no'} |" for r in h["rows"]]
        L.append("")

    L += ["## Calibration", "",
          "Fitted 90%-interval factor k per tier (k = 1: prior error model was right; "
          "k > 1: intervals were too narrow):", ""]
    for tier, v in results["calibration_fit"].items():
        L.append(f"- {tier}: k = {v['k']:.2f} (n = {v['n']} measurements)")

    L += ["", "## Timing", "", "| capture | tier | seconds |", "|---|---|---|"]
    L += [f"| {cid} | {s['tier']} | {_num(s['timing_s'], 1)} |" for cid, s in C.items()]
    path.write_text("\n".join(L) + "\n", encoding="utf-8")
